Definition ecparams_result (ca : Z -> curve_addrs) (ONE : Z) (C : Z) (g0 : ecp_grp) (r : Z) (g' : ecp_grp) (NB : list blk) : Prop :=
  (exists id, 0 <= id < 2^31 /\ gl_result ca ONE id C r g' NB) \/ (r <> 0 /\ g' = g0 /\ NB = []).

